173:     #[test]
174:     fn test_journal_covers_range() {
175:         let range: NonEmptyRange<Location<MmrFamily>> =
176:             non_empty_range!(Location::new(10), Location::new(20));
177: 
178:         // Bounds reaching at least back to the start and ending exactly at the end cover.
179:         assert!(journal_covers_range(10..20, &range));
180:         assert!(journal_covers_range(5..20, &range));
181: 
182:         // Bounds starting after the range start do not cover.
183:         assert!(!journal_covers_range(11..20, &range));
184: 
185:         // Bounds ending anywhere but exactly at the range end do not cover.
186:         assert!(!journal_covers_range(10..19, &range));
187:         assert!(!journal_covers_range(10..21, &range));
188:         assert!(!journal_covers_range(0..0, &range));
189:     }
